function ReturnWorkflow({row,onClose,onDone}:{row:RentalRow|null;onClose:()=>void;onDone:()=>Promise<void>}){const [step,setStep]=useState(0);const [form,setForm]=useState<ReturnForm>(returnInitial);const [saving,setSaving]=useState(false);const [readingPhotos,setReadingPhotos]=useState(false);const [error,setError]=useState('');useEffect(()=>{if(row){setStep(0);setForm(returnInitial)}},[row]);const inspectionContext=useRentalInspection(row?.id,'PostHire');const checks=categoryChecks(row);const checklist=inspectionContext.items??checklistFor(row);const charges=['late','excess','refuelling','cleaning','damageCharge','other'].reduce((sum,key)=>sum+Number(form[key as keyof ReturnForm]||0),0);const validBond=Number(form.bondDeduction||0)>=0&&Number(form.bondDeduction||0)<=(row?.bondAmountHeld??0)&&(Number(form.bondDeduction||0)===0||Boolean(form.bondReason.trim()));const ready=[form.scannedAssetNumber.trim().toUpperCase()===row?.assetNumber?.toUpperCase(),true,!checks.tracksMeter||form.meter!==''&&form.fuel!=='',Boolean(form.condition.trim())&&(form.damageZones.length===0||Boolean(form.damage.trim()))&&checklist.every(item=>form.checklistItems.includes(item))&&form.evidenceDataUrls.length>0,true,true,validBond,Boolean(form.signature.trim()&&form.signatureDataUrl&&form.acknowledged),true]
  async function complete(){if(!row)return;setSaving(true);try{await api.post(`/rentals/${row.id}/return`,{scannedAssetNumber:form.scannedAssetNumber,identificationVerified:true,driverLicenceVerified:true,meterReading:checks.tracksMeter?Number(form.meter):null,fuelLevelPercent:checks.tracksFuel?Number(form.fuel):null,conditionNotes:form.condition,damageNotes:form.damage||null,signatureName:form.signature,signatureDataUrl:form.signatureDataUrl,additionalCharges:Number(form.other),additionalChargesDescription:form.otherReason||null,lateFee:Number(form.late),excessUsageCharge:Number(form.excess),refuellingCharge:Number(form.refuelling),cleaningCharge:Number(form.cleaning),damageCharge:Number(form.damageCharge),bondDeductionAmount:Number(form.bondDeduction),bondDeductionReason:form.bondReason||null,bondRefundMethod:form.bondRefundMethod,evidenceDataUrls:form.evidenceDataUrls,damageZones:form.damageZones,accessoryNotes:form.accessoryNotes,checklistItems:form.checklistItems},{timeout:60000});await onDone()}catch(reason){setError(err(reason,'The return could not be completed.'))}finally{setSaving(false)}}
  return <Dialog open={Boolean(row)} onClose={()=>!saving&&!readingPhotos&&onClose()} fullScreen><DialogTitle sx={{borderBottom:1,borderColor:'divider'}}><Typography variant="overline" color="text.secondary">Guided return</Typography><Typography variant="h5" fontWeight={850}>{row?.bookingNumber} · {row?.assetName}</Typography></DialogTitle><DialogContent sx={{p:{xs:2,md:4}}}><Stepper activeStep={step} alternativeLabel sx={{display:{xs:'none',md:'flex'},mb:4}}>{returnSteps.map((label,index)=><Step key={label} completed={index<step}><StepLabel>{label}</StepLabel></Step>)}</Stepper><Box sx={{maxWidth:900,mx:'auto'}}><Typography variant="overline" color="text.secondary">Step {step+1} of {returnSteps.length}</Typography><Typography variant="h5" fontWeight={800} mb={3}>{returnSteps[step]}</Typography>{error&&<Alert severity="error" sx={{mb:2}}>{error}</Alert>}{inspectionContext.error&&<Alert severity="error">{inspectionContext.error}</Alert>}
    {step===0&&<Stack alignItems="center" spacing={2}><QrCodeScannerOutlined sx={{fontSize:80,color:'secondary.main'}}/><Typography fontWeight={800}>{row?.assetName} · {row?.assetNumber}</Typography><Alert severity="info">Scan the physical asset label to prevent returning the wrong asset against this hire.</Alert><TextField fullWidth required label="Scan or enter returned asset QR number" value={form.scannedAssetNumber} onChange={e=>setForm({...form,scannedAssetNumber:e.target.value})} error={Boolean(form.scannedAssetNumber)&&form.scannedAssetNumber.toUpperCase()!==row?.assetNumber?.toUpperCase()} helperText={`Expected asset: ${row?.assetNumber??'Not allocated'}`}/></Stack>}
    {step===1&&<ReviewCard title="Rental being returned" rows={[['Customer',row?.customerName],['Contact',row?.customerPhone||'Not recorded'],['Asset',`${row?.assetName} (${row?.assetNumber})`],['Expected return',date(row?.endAt??null,true)],['Agreement',row?.agreementStatus]]}/>}
    {step===2&&(checks.tracksMeter?<Grid container spacing={2}><Grid size={{xs:12,sm:6}}><TextField fullWidth required type="number" label="Return odometer / operating hours" value={form.meter} onChange={e=>setForm({...form,meter:e.target.value})}/></Grid><Grid size={{xs:12,sm:6}}><TextField fullWidth required type="number" inputProps={{min:0,max:100}} label="Returned fuel / battery level (%)" value={form.fuel} onChange={e=>setForm({...form,fuel:e.target.value})}/></Grid></Grid>:<Alert severity="info">This category has no odometer, hour meter, fuel or battery reading. Confirm quantities and physical condition in the inspection.</Alert>)}
    {step===3&&<Stack spacing={2}>{checks.tracksMeter?<Grid container spacing={2}><Grid size={{xs:12,sm:6}}><TextField fullWidth required type="number" label="Return odometer / operating hours" value={form.meter} onChange={e=>setForm({...form,meter:e.target.value})}/></Grid><Grid size={{xs:12,sm:6}}><TextField fullWidth required type="number" inputProps={{min:0,max:100}} label="Returned fuel / battery level (%)" value={form.fuel} onChange={e=>setForm({...form,fuel:e.target.value})}/></Grid></Grid>:<Alert severity="info">This category has no odometer, hour meter, fuel or battery reading.</Alert>}<Typography fontWeight={750}>{inspectionContext.templateName||"Required checklist"}</Typography><Grid container spacing={1}>{checklist.map(item=><Grid key={item} size={{xs:12,md:6}}><FormControlLabel control={<Checkbox checked={form.checklistItems.includes(item)} onChange={e=>setForm({...form,checklistItems:e.target.checked?[...form.checklistItems,item]:form.checklistItems.filter(x=>x!==item)})}/>} label={item}/></Grid>)}</Grid><Button size="small" variant="outlined" sx={{alignSelf:'flex-start'}} onClick={()=>setForm({...form,checklistItems:form.checklistItems.length===checklist.length?[]:checklist})}>{form.checklistItems.length===checklist.length?'Clear all checklist items':'Check all checklist items'}</Button><TextField fullWidth required multiline minRows={4} label="Post-hire inspection result" value={form.condition} onChange={e=>setForm({...form,condition:e.target.value})} helperText={checks.guidance}/><TextField fullWidth multiline minRows={3} label="New damage or fault" value={form.damage} onChange={e=>setForm({...form,damage:e.target.value})}/><TextField fullWidth multiline label="Accessories and quantities" helperText="Record issued / returned items, quantities and any missing items." value={form.accessoryNotes} onChange={e=>setForm({...form,accessoryNotes:e.target.value})}/><DamageLocations value={form.damageZones} onChange={damageZones=>setForm({...form,damageZones})}/><InspectionPhotos onBusyChange={setReadingPhotos} photos={form.evidenceDataUrls} onChange={photos=>setForm(current=>({...current,evidenceDataUrls:photos}))}/></Stack>}
    {step===4&&<Stack spacing={2}>{inspectionContext.preHire?<Alert severity="success">A saved pre-hire inspection was loaded. Review it and save any changes.</Alert>:<Alert severity="info">No pre-hire inspection is saved yet. Complete the checklist and attach photos, then save.</Alert>}<EvidenceComparison evidenceJson={inspectionContext.preHire?.evidenceJson} photos={form.evidenceDataUrls}/><Alert severity={form.damage?'warning':'success'}>{form.damage?'New damage or a fault is recorded. CREMS will route the asset to Inspection instead of Available.':'No new damage is recorded. CREMS will return the asset to Available after completion.'}</Alert><ReviewCard title="Pre- vs post-hire comparison" rows={[['Pre-hire condition',row?.preHireCondition||'Missing'],['Starting reading',row?.preHireMeterReading==null?'Not applicable':String(row.preHireMeterReading)],['Starting fuel / battery',row?.preHireFuelLevelPercent==null?'Not applicable':row.preHireFuelLevelPercent+'%'],['Return meter',form.meter||'Not entered'],['Return fuel',form.fuel?`${form.fuel}%`:'Not entered'],['New condition',form.condition||'Not entered'],['Damage / fault',form.damage||'None reported']]}/></Stack>}
    {step===5&&<Stack spacing={2}><Grid container spacing={2}>{([['late','Late return'],['excess','Excess usage'],['refuelling','Refuelling'],['cleaning','Cleaning'],['damageCharge','Damage'],['other','Other']] as const).map(([key,label])=><Grid key={key} size={{xs:12,sm:6,md:4}}><TextField fullWidth type="number" label={`${label} (FJD)`} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/></Grid>)}</Grid><TextField fullWidth label="Other charge reason" value={form.otherReason} onChange={e=>setForm({...form,otherReason:e.target.value})}/><Card variant="outlined"><CardContent><Stack direction="row" justifyContent="space-between"><Typography fontWeight={750}>Additional charges before VAT</Typography><Typography variant="h5" fontWeight={850}>{money(charges)}</Typography></Stack></CardContent></Card></Stack>}
    {step===6&&<Stack spacing={2}><Typography>Settle the refundable bond separately from the final rental charges.</Typography><Card variant="outlined"><CardContent><Typography fontWeight={800} mb={2}>Refundable bond settlement</Typography><ReviewCard title="Bond held" rows={[["Required",money(row?.depositRequired??0)],["Held",money(row?.bondAmountHeld??0)],["Refund due",money(Math.max(0,(row?.bondAmountHeld??0)-Number(form.bondDeduction||0)))]]}/><Grid container spacing={2} mt={1}><Grid size={{xs:12,sm:6}}><TextField fullWidth type="number" inputProps={{min:0,max:row?.bondAmountHeld??0}} label="Bond deduction (FJD)" value={form.bondDeduction} onChange={e=>setForm({...form,bondDeduction:e.target.value})}/></Grid><Grid size={{xs:12,sm:6}}><TextField fullWidth select SelectProps={{native:true}} label="Refund method" value={form.bondRefundMethod} onChange={e=>setForm({...form,bondRefundMethod:e.target.value})}><option>Card</option><option>Cash</option><option>BankTransfer</option><option>MobileMoney</option></TextField></Grid></Grid>{Number(form.bondDeduction)>0&&<TextField sx={{mt:2}} required fullWidth multiline minRows={2} label="Evidence-based deduction reason" value={form.bondReason} onChange={e=>setForm({...form,bondReason:e.target.value})}/>}</CardContent></Card></Stack>}
    {step===7&&<Stack spacing={2}><Typography>Review the return condition, charges and bond settlement with the customer.</Typography><TextField required fullWidth label="Customer acknowledgement name" value={form.signature} onChange={e=>setForm({...form,signature:e.target.value})}/><SignaturePad value={form.signatureDataUrl} onChange={signatureDataUrl=>setForm({...form,signatureDataUrl})}/><FormControlLabel control={<Checkbox checked={form.acknowledged} onChange={e=>setForm({...form,acknowledged:e.target.checked})}/>} label="Customer acknowledges the return record, charges and refundable bond settlement"/></Stack>}
    {step===8&&<Stack spacing={2}><Alert severity="info">Completing the return will create the final invoice, notify the customer, record lifecycle and audit events, and automatically choose Available or Inspection based on the reported condition.</Alert><ReviewCard title="Return outcome" rows={[['Asset next status',form.damage?'Inspection':'Available'],['Additional charges',money(charges)],['Bond refund',money(Math.max(0,(row?.bondAmountHeld??0)-Number(form.bondDeduction||0)))],['Customer acknowledgement',form.signature],['Maintenance referral',form.damage?'Required from inspection':'Not required']]}/></Stack>}
  </Box></DialogContent><DialogActions sx={{p:2,borderTop:1,borderColor:'divider'}}><Button disabled={saving||readingPhotos} onClick={onClose}>Cancel return</Button><Box sx={{flex:1}}/><Button disabled={step===0||saving||readingPhotos} onClick={()=>setStep(v=>v-1)}>Back</Button>{step<returnSteps.length-1?<Button variant="contained" disabled={!ready[step]||readingPhotos||inspectionContext.loading||Boolean(inspectionContext.error)} onClick={()=>setStep(v=>v+1)}>Continue</Button>:<Button variant="contained" disabled={!ready.every(Boolean)||saving||readingPhotos||inspectionContext.loading||Boolean(inspectionContext.error)} onClick={()=>void complete()}>{saving?'Completing return…':'Complete return & create invoice'}</Button>}</DialogActions></Dialog>}

function ReviewCard({title,rows}:{title:string;rows:[string,string|undefined|null][]}){return <Card variant="outlined"><CardContent><Typography variant="h6" fontWeight={800} mb={2}>{title}</Typography><Grid container spacing={2}>{rows.map(([label,value])=><Grid key={label} size={{xs:12,sm:6}}><Typography variant="caption" color="text.secondary">{label}</Typography><Typography fontWeight={650}>{value||'Not recorded'}</Typography></Grid>)}</Grid></CardContent></Card>}
